import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Cross-Platform Architecture","description":"","frontmatter":{"title":"Cross-Platform Architecture"},"headers":[],"relativePath":"guide/platforms.md","filePath":"guide/platforms.md","lastUpdated":1793266312000}`),a={name:`guide/platforms.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_11-cross-platform-architecture" tabindex="-1">11. Cross-Platform Architecture <a class="header-anchor" href="#_11-cross-platform-architecture" aria-label="Permalink to “11. Cross-Platform Architecture”">​</a></h1><h2 id="_11-1-unified-platform-interfaces" tabindex="-1">11.1 Unified platform interfaces <a class="header-anchor" href="#_11-1-unified-platform-interfaces" aria-label="Permalink to “11.1 Unified platform interfaces”">​</a></h2><p>The following abstractions are suggested:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProcessController</span></span>
<span class="line"><span>ServiceController</span></span>
<span class="line"><span>NetworkInterfaceController</span></span>
<span class="line"><span>NetworkConnectivityProbe</span></span>
<span class="line"><span>CredentialProvider</span></span>
<span class="line"><span>SystemRebootController</span></span></code></pre></div><p>Each interface only defines cross-platform common semantics. Platform-specific capabilities are described through Capabilities; platform support must never be faked for the sake of a unified interface.</p><h2 id="_11-2-windows" tabindex="-1">11.2 Windows <a class="header-anchor" href="#_11-2-windows" aria-label="Permalink to “11.2 Windows”">​</a></h2><p>Capabilities to support progressively include:</p><ul><li>Process detection.</li><li>Windows Service control.</li><li>Wi-Fi state detection.</li><li>Wi-Fi reconnection.</li><li>Network interface reset.</li><li>DNS flush.</li><li>IP configuration checks.</li><li>Default gateway checks.</li><li>Network connectivity checks.</li><li>Sunlogin process or service checks.</li><li>Authorized system reboot.</li></ul><p>Wi-Fi reconnection involves credentials, network adapters and system privileges; use system-supported APIs or controlled commands.</p><p>If resetting a network adapter could interrupt the management connection, the risk must be explicitly marked in policy.</p><h2 id="_11-3-linux" tabindex="-1">11.3 Linux <a class="header-anchor" href="#_11-3-linux" aria-label="Permalink to “11.3 Linux”">​</a></h2><p>Needs to support:</p><ul><li>Process detection.</li><li>systemd service control.</li><li>OpenRC adaptation later.</li><li>Network interface state.</li><li>IP and route checks.</li><li>DNS checks.</li><li>Controlled command execution.</li><li>System reboot.</li></ul><p>Do not assume every Linux system uses systemd.</p><h2 id="_11-4-macos" tabindex="-1">11.4 macOS <a class="header-anchor" href="#_11-4-macos" aria-label="Permalink to “11.4 macOS”">​</a></h2><p>Later support:</p><ul><li>Process detection.</li><li>launchd service management.</li><li>Network interface state.</li><li>Wi-Fi reconnection.</li><li>Network connectivity checks.</li><li>System reboot.</li></ul><h2 id="_11-5-bsd" tabindex="-1">11.5 BSD <a class="header-anchor" href="#_11-5-bsd" aria-label="Permalink to “11.5 BSD”">​</a></h2><p>Later support:</p><ul><li>Process detection.</li><li>rc.d service management.</li><li>Network interface and route state.</li><li>System reboot.</li></ul><h2 id="_11-6-openwrt" tabindex="-1">11.6 OpenWrt <a class="header-anchor" href="#_11-6-openwrt" aria-label="Permalink to “11.6 OpenWrt”">​</a></h2><p>Later support:</p><ul><li>procd service management.</li><li>UCI configuration reading and controlled modification.</li><li>ubus calls.</li><li>Network interface and route checks.</li><li>OpenClash state detection.</li><li>Proxy node switching.</li><li>Service restart.</li></ul><p>Every network and firewall change must have a clear scope of effect, preconditions, risk level and verification steps.</p><p>Clearing firewall rules by default, resetting all routes, or unconditionally overwriting the existing network configuration is forbidden.</p><hr>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};